  ('manaus-amazon-brazil', '10S', 'Manaus & the Brazilian Amazon', 'Brazil', 'Where two great rivers meet', 'live', 'verified', 'desertDunes', 'Amazon, Pantanal & Iguaçu', '{"adventure","river","romance","wildlife"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":null,"safety":{"emergency":"190","emergency_medical":"192","advisory_source":"https://www.gov.uk/foreign-travel-advice/brazil","book_enabled":true,"air_access_verified":{"international":"MAO (Eduardo Gomes International, Manaus) — direct Miami + Panama City","domestic":"MAO — São Paulo / Brasília / Belém via LATAM, Gol, Azul"},"remote_flag":true,"malaria":"low in urban Manaus, real in deep-forest lodges — prophylaxis a lodge+season decision with a travel clinic","vaccinations":["yellow fever (required-in-practice, all Manaus travelers, ≥10 days pre-travel, single lifetime dose)","routine (DTP, MMR, polio, hep A/B) up to date"],"water":"bottled / lodge-treated only (no untreated river or tap water)","caveats":["High-vs-low water: the trip changes with the season — set expectations","Yellow fever vaccine required-in-practice ≥10 days pre-travel","Malaria prophylaxis for deep-forest lodges; dengue/Zika/chikungunya year-round, active 2026","Jungle-lodge remoteness — hours by river from Manaus hospitals; confirm evac insurance","Manaus urban crime — vetted transport, discreet valuables, night-area discipline","River safety — lifejackets on all transfers/excursions"],"fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/brazil","read":"2026-08-20T14:54:23Z","page_updated":"2026-05-11T12:32:48+01:00","source_country":"brazil","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"River areas in the west of Amazonas State","lvl":3,"posture":"all-but-essential","note":"Along the Amazon River and its tributaries west of Codajás and east of Belém do