  ('mexico-city-mexico', '10S', 'Mexico City (CDMX)', 'Mexico', 'The beating heart of the Americas', 'live', 'verified', 'kyoto', 'Mexico City', '{"romance","culture","culinary","entertainment"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["Anchor of the Central Mexico block — culture, food, and history mega-destination; folds in Centro Histórico, Coyoacán, Roma-Condesa, Polanco, Chapultepec, Xochimilco, Basílica de Guadalupe + Teotihuacán day-trip","Museo Nacional de Antropología holds the Aztec Sun Stone — Mexico''s largest and most-visited museum","Pujol / Quintonil / Contramar form the ''holy trinity'' of CDMX dining; Pujol is top-5 on Latin America''s list","Día de Muertos (Oct 31–Nov 2) is the cultural apex — ~6 km Grand Parade Chapultepec → Reforma → Zócalo (~Nov 1)","Sits at ~2,240 m (7,349 ft) — ~25% less oxygen than sea level; 24–72 hr acclimatization typical"],"safety":{"emergency":"911","hospital":"Centro Médico ABC (International Patient dept, English-speaking); Hospital Ángeles (Lomas/Pedregal); Médica Sur. Air-ambulance evac via insurer.","book_enabled":true,"air_access_verified":"MEX/AICM (primary international) + AIFA/NLU Felipe Ángeles (secondary; Tren FA to Buenavista opened Apr 2026)","altitude":"~2,240 m (7,349 ft) — AMS note for sensitive travelers; 24–72 hr acclimatization; guided-only for Izta-Popo/Nevado de Toluca volcano day-hikes","malaria":"none (altitude >2,000 m is above vector zone)","water":"bottled/purified only; tap not for drinking","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","page_updated":"2026-07-16T16:08:09+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}],"fcdo_zones_provenance":{"file":"src/data/safety.json","ref":"f8666636bc25790e0c9643ad5656f8d9fea37bf6","ref_committed":"2026-08-30T05:44:55Z","country_iso2":"MX","summary":"The FCDO advises against all but essential travel to named states, cities and border areas of Mexico — listed below in its own words, each with its own exceptions. The Yucatán Peninsula, Mexico City, Baja California Sur and the other main visitor regions carry no FCDO restriction.","source":"UK FCDO — Mexico travel advice, reviewed 2026-07-16 (verbatim snapshot from the research library)","_rule":"the FCDO restricted-area records for this country, verbatim. PRESENCE OF THIS BLOCK IS NOT A CLAIM THAT THIS DESTINATION SITS IN ANY OF THEM — membership is a coverage judgement and is set only in `zone_record`, by a human."}},"timing":{"inflection_curve_start":"early-to-mid September (Día de Muertos peak); mid-February (spring jacaranda/Semana Santa peak)","peak":"Oct 31 – Nov 2 (Día de Muertos; Grand Parade ~Nov 1). Secondary: Mar–Apr (jacaranda + Semana Santa)","fire_date":"2026-08-25 (Día de Muertos primary); ~2026-02-20 (spring secondary)","shoulder":"May, September","green":"June–September (afternoon rains, mornings clear, lowest rates)","booking_lead":"Centro/Reforma weeks-out for Día de Muertos; Casa Barragán tickets release Tue noon CDMX (sell out in minutes); Teotihuacán balloon + Casa Azul 2–4 weeks ahead; top restaurants weeks ahead","off_season_specials":"June–Sep green-season value stays — weather-resilient (rain is afternoon-only); ''same museums, same Pujol, half the room rate''","event_peaks":["Día de Muertos Oct 31–Nov 2 (marquee)","Jacaranda bloom Mar–Apr","Grito de Independencia Sep 15–16","Semana Santa (moveable Mar/Apr)"]},"jewels":[{"name":"Teotihuacán dawn hot-air balloon","si_tag":"Culture & Heritage","status":"future","hook":"float over the Pyramid of the Sun as the Avenue of the Dead emerges from mist","bookable_category":"private tour/experience","tier":"luxury","source":"https://www.colima71.com/signature-experiences-mexico-city/hot-air-balloon-in-teotihuacan-experience — Accessed 2026-07-05","timing":"Oct 31","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"float over the Pyramid of the Sun as the Avenue of the Dead emerges from mist","when":"Oct 31","commission":"Journey Mexico (Fora) or affiliate ~8%","accessed":"2026-07-05","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","entertainment":"destination","romance":"destination"}