is":"band+lane"},{"name":"Basílica de Guadalupe","si_tag":"Culture & Heritage","status":"future","hook":"most-visited Catholic pilgrimage site in the Americas; the tilma of Juan Diego","bookable_category":"private half-day tour","tier":"comfort","source":"https://www.casagoliana.com/blog/best-time-to-visit-mexico-city/ — Accessed 2026-07-05","timing":"Oct 31","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"most-visited Catholic pilgrimage site in the Americas; the tilma of Juan Diego","when":"Oct 31","commission":"DMC/affiliate","accessed":"2026-07-05","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","entertainment":"destination","romance":"destination"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Coyoacán + Museo Frida Kahlo (Casa Azul)","si_tag":"Culture & Heritage","status":"future","hook":"the cultural heart; Frida''s cobalt-blue house + cobblestone plazas","bookable_category":"combo tour (often w/ Xochimilco)","tier":"comfort","source":"https://amigotours.com/mexico-city-tours/xochimilco-coyoacan-frida-kahlo-museum-tour/ — Accessed 2026-07-05","timing":"Oct 31","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"the cultural heart; Frida''s cobalt-blue house + cobblestone plazas","when":"Oct 31","commission":"affiliate ~8% (Viator) or DMC private","accessed":"2026-07-05","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","entertainment":"destination","romance":"destination"},"commission_pct_low":8,"commission_pct_high":8,"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Casa Luis Barragán (UNESCO)","si_tag":"Culture & Heritage","status":"future","hook"