  ('monteverde-costa-rica', '10S', 'Monteverde', 'Costa Rica', 'The original cloud forest', 'live', 'verified', 'mountainValley', 'Costa Rica', '{"expedition","wildlife","romance"}', '{}', '{"essential","premier","ultra"}', null, null, '{"key_facts":["Birthplace of the commercial canopy zipline; Selvatura runs 13 ziplines incl. a 1 km line, 15 platforms, Tarzan swing, and 8 hanging bridges (51-170 m long, 12-60 m high).","Cloud forest protects 400+ bird species (resplendent quetzal, three-wattled bellbird), 2,500+ plants incl. 500+ orchids, 100+ mammals.","Three reserves: Monteverde Cloud Forest ($25, 7AM-4PM), Santa Elena (quieter, great quetzals), Curi-Cancha (least crowded, top birding).","Resplendent quetzal breeds Feb-Jun (peak Mar-Apr), best viewed 6-9 AM on wild-avocado trees.","Highland ~1,400 m; ~3-4 hr from SJO with a rough, partly-unpaved final mountain road; dengue risk low at elevation."],"safety":{"emergency":"911","nearest_clinic":"Santa Elena local clinics (minor/first response)","major_trauma":"San Jose hospitals (CIMA, Clinica Biblica), ~3-4 hr by road; air/ground evac pathway","advisory_reason":"Crime (petty nationwide; some violent crime, concentrated in specific San Jose neighborhoods)","advisory_issued":"2026-04-02","standard_caution":"No valuables in parked rental cars; registered operators; daylight driving on mountain road","activity_hazards":["zipline/canopy operator certification + harness/brakes + weight limits","mountain-road fog + unpaved sections (4WD, daylight)","night-walk footing + vipers (guided only)","wet suspension-bridge decking + heights"],"book_enabled":true,"air_access_verified":"SJO (Juan Santamaria) ~3-4 hr road; note rough/partly-unpaved access road","water":"Tap water generally potable including Monteverde area; bottled optional for sensitive travelers","dengue":"Low at ~1,400 m highland elevation; use repellent","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/costa-rica","read":"2026-08-20T14:54:18Z","page_updated":"2026-05-19T11:42:25+01:00","source_country":"costa-rica","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"national_dry_peak":"mid-December to April","holiday_hard_peak":"late December","quetzal_breeding":"February to June/July, peak March-April","green_secret_season":"May-June (low crowds, birding-rich, misty year-round)","wettest_month":"October","curve_start_dry":"early-mid December","curve_start_quetzal":"early February","fire_date":"late November (~Nov 20-27) for dry/holiday; mid-late January (~Jan 20-27) for quetzal-birding","booking_lead":"60-90 days peak; 2-4 weeks green season","note":"misty year-round; peak demand != peak experience; sharpen on live tracking"},"jewels":[{"name":"Selvatura Park canopy + bridges","si_tag":"expedition","tier":"essential","source":"https://www.selvatura.com/","timing":"year-round","timing_type":"ALWAYS-ON","si":"expedition","when":"year-round","commission":"Activities-Well direct or DMC bundle","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"expedition":"primary","romance":"destination","wildlife":"destination"},"commission_lane":["DMC","bundle"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Sky Adventures (SkyTram/SkyTrek/SkyWalk)","si_tag":"expedition","tier":"essential","source":"https://eternalarrival.com/ziplining-in-monteverde-canopy-tours/","si":"expedition","commission":"Activities-Well / DMC","wells":["move"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"expedition":"primary","romance":"destination","wildlife":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"100% Aventura (Superman ziplines)","si_tag":"expedition","tier":"essential","source":"https://mytanfeet.com/activities/100-aventura-monteverde/","si":"expedition","commission":"Activities-Well / DMC","well