ission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Hierve el Agua","si_tag":"expedition","tier":"essential","source":"https://www.mexicotravelandleisure.com/blog/hierve-el-agua-oaxaca/","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"~50 MXN site entry + separate communal road toll + ~30 MXN parking, cash only, no on-site ATM. Non-commissionable","si":"expedition","blurb":"~50 MXN site entry + separate communal road toll + ~30 MXN parking, cash only, no on-site ATM. Non-commissionable","when":"Dia de Muertos Oct 31–Nov 2","commission":"guided valley day-trip + ~50 MXN entry pass-through (VERIFY OPEN)","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["expedition"],"shelf_fit":{"expedition":"primary","romance":"destination"},"commission_lane":["guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Santiago Matatlan mezcal route","si_tag":"expedition","tier":"premier","source":"https://www.oaxaca-mio.com/mezcalesdeoaxaca/matatlan.htm","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"Dia de Muertos Oct 31–Nov 2","commission":"guided mezcal-route tour (DMC/Viator); bottles non-commissionable","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["expedition"],"shelf_fit":{"expedition":"primary","romance":"destination"},"commission_lane":["DMC","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"El Tule (world''s widest tree)","si_tag":"expedition","tier":"essential","source":"https://culturestraveled.com/hierve-el-agua-oaxaca/","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"At Santa María del Tule, ~20 minutes from the city","si":"expedition","blurb":"At Santa María del Tule, ~20 minutes from the city","when":"Dia de Muertos Oct 31–Nov 2","commission":"bundled into valley-circuit tour","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["expedition"],"shelf_fit":{"expedition":"primary","romance":"destination"},"commission_lane":["bundle"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Teotitlan del Valle weavers","si_tag":"romance","tier":"premier","source":"https://brokenbootstravel.com/the-travelers-guide-to-teotitlan-del-valle/","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Dia de Muertos Oct 31–Nov 2","commission":"private artisan-village tour (DMC); rug purchases direct-to-artisan","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["romance"],"shelf_fit":{"expedition":"destination","romance":"primary"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"San Bartolo Coyotepec black pottery","si_tag":"romance","tier":"essential","source":"https://theculturetrip.com/north-america/mexico/articles/a-tour-of-oaxacas-best-markets","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Dia de Muertos Oct 31–Nov 2","commission":"south-valley artisan tour (DMC)","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["romance"],"shelf_fit":{"expedition":"destination","romance":"primary"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Alebrijes at San Martin Tilcajete","si_tag":"romance","tier":"comfort","source":"https://www.fiestamericanatravelty.com/en/grand-fiesta-americana/hotels/grand-fiesta-americana-oaxaca","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Dia de Muertos Oct 31–Nov 2","commission":"artisan-workshop tour + hotel alebrije programming","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["romance"],"shelf_fit":{"expedition":"destination","romance":"primary"},"commission_lane":["hotel"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What''s the real risk to plan for?","a":"Terrain and high-proof spirits, not crime. The city is a mild **~1,555 m** (light first-day breathlessness at most); the genuine hazards are Hierve el Agua''s cliff-edge footing above a canyon and the mezcal route — high-proof tastings plus rural highway driving mean you take a driver or DMC, never self-drive after tasting.","source":"oaxacalife.com, 2026-07-05","si_tag":"safety"},{"q":"When is Día de Muertos, and how far ahead do I book?","a":"Oct 31–Nov 2, and it''s the longest lead time in the inland catalog: book **4–8 months ahead** (5–6 months / May–June is the sweet spot). Walkable-Centro rooms are ~95% booked by early September and rates run **2–3× normal** ($150–250 USD/night).","source":"mexicotravelandleisure.com / wheregoesrose.com, 2026-07-05","si_tag":"culture"},{"q":"Is Oaxaca really a top food destination?","a":"Yes — it''s widely regarded as one of the world''s great food capitals. The \"seven moles,\" market-to-table cooking schools (Casa Crespo), and the mezcal terroir of Santiago Matatlán (~45 minutes southeast, the World Capital of Mezcal) are destination-defining reasons to go.","source":"oaxaca-mio.com, 2026-07-05","si_tag":"culinary"},{"q":"Is Hierve el Agua worth it — and will it be open?","a":"Worth it, but verify first. The petrified mineral \"waterfalls\" and clifftop spring-fed pools sit 70 km east near Mitla, but the site sees **periodic community-dispute closures clustering June–October** — always confirm it''s open the week before, and keep a Mitla + Tlacolula fallback ready.","source":"mexicotravelandleisure.com, 2026-07-05","si_tag":"expedition"},{"q":"Is Oaxaca good for couples?","a":"Yes — a slow, sensory, non-beach romance. Boutique casonas and the ex-convent (1576) Quinta Real, mezcal-tasting date nights, and the artisan-village shopping ritual (Teotitlán weaving, rugs $75–$500; San Bartolo black pottery; alebrijes) make the case.","source":"caminoreal.com / brokenbootstravel.com, 2026-07-05","si_tag":"romance"}],"seo":{"meta_title":"Oaxaca City & the Central Valleys, Mexico — UNESCO, Mezcal, Dia de Muertos & Monte Alban | TravelWell.World","search_language":["en","es-MX"],"local_keywords":["Dia de Muertos Oaxaca","que hacer en Oaxaca","ruta del mezcal","Guelaguetza fechas","Monte Alban precio entrada","Hierve el Agua abierto","hoteles boutique Oaxaca centro","Noche de Rabanos"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-05","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-05","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":["romance","expedition"],"ultra":[{"name":"Quinta Real Oaxaca","positioning":"ex-Convent of Santa Catalina (1576), 91 rooms, UNESCO Centre","earning_path":"consortia/Virtuoso + Fora lane","mor":"hotel","tier":"ultra"},{"name":"Escondido Oaxaca","positioning":"Grupo Habita design-boutique, rooftop pool","earning_path":"Grupo Habita direct + consortia/Fora","mor":"hotel","tier":"ultra"},{"name":"Pug Seal Oaxaca","positioning":"top-cited Centro design-boutique","earning_path":"consortia/Fora","mor":"hotel","tier":"ultra"},{"name":"Hotel Sin Nombre","positioning":"intimate quiet-luxury design hotel","earning_path":"Fora/direct","mor":"hotel","tier":"ultra"},{"name":"Casa Antonieta","positioning":"9-room boutique casona, affordable-ultra entry","earning_path":"OTA + boutique-collection/Fora","mor":"hotel","tier":"premier"}],"source_verified":"2026-07-05","hero":{"query":"Oaxaca City & the Central Valleys, Mexico"},"geo":{"lat":17.0732,"lng":-96.7266},"orbit":[{"id":"huatulco-mexico","jewels":10,"si":["expedition","diveglobal","ocean","culture","wildlife","wellness"]},{"id":"puerto-escondido-mexico","jewels":10,"si":["expedition","romance","tropical","wildlife","culture"]}],"orbit_country":["akumal-mexico","bacalar-mexico","balandra-beach-mexico","cabo-pulmo-mexico","cabo-san-lucas-mexico","calakmul-mexico","campeche-city-mexico","cancun-mexico","careyes-mexico","celestun-mexico","chapala-ajijic-mexico","chichen-itza-mexico","coba-mexico","costalegre-mexico","cozumel-mexico","east-cape-mexico","ensenada-mexico","espiritu-santo-island-mexico","guadalajara-mexico","guanajuato-city-mexico","holbox-mexico","isla-contoy-mexico","isla-mujeres-mexico","izamal-mexico","la-paz-mexico","loreto-mexico","los-barriles-mexico","magdalena-bay-mexico","mahahual-mexico","mazamitla-mexico","merida-mexico","mexico-city-mexico","palenque-mexico","playa-del-carmen-mexico","puerto-aventuras-mexico","puerto-morelos-mexico","puerto-vallarta-mexico","punta-mita-mexico","rio-lagartos-mexico","san-cristobal-de-las-casas-mexico","san-jose-del-cabo-mexico","san-miguel-de-allende-mexico","san-sebastian-del-oeste-mexico","sayulita-mexico","sian-kaan-mexico","teotihuacan-mexico","tlaquepaque-mexico","todos-santos-mexico","tulum-mexico","uxmal-mexico","valladolid-mexico","valle-de-guadalupe-mexico"]}'::jsonb, 72),
