ant","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"expedition":"primary","wellness":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Volcán Maderas summit + crater lagoon (1,394 m)","si_tag":"expedition","tier":"essential","source":"https://ometepenicaragua.com/volcanoes/","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"dormant cone crowned by cloud forest and a still crater lake you can swim in. price","si":"expedition","blurb":"dormant cone crowned by cloud forest and a still crater lake you can swim in. price","when":"Dry season Dec–Apr","commission":"dormant","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"expedition":"primary","wellness":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Río Istián kayak","si_tag":"expedition","tier":"essential","source":"https://ometepenicaragua.com/istian/index.php","hook":"moderate · guided/rental. ~4-hr paddle from Mérida through wetland channels; wildlife-rich; watch lake wind on the open-water leg","si":"expedition","blurb":"moderate · guided/rental. ~4-hr paddle from Mérida through wetland channels; wildlife-rich; watch lake wind on the open-water leg","commission":"dormant","wells":["activities","gear"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"expedition":"primary","wellness":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"San Ramón waterfall (64 m)","si_tag":"expedition","tier":"essential","source":"https://www.theselvistaexperience.com/hiking-san-ramon-waterfall","hook":"moderate hike. ~64 m fall on Maderas above Mérida, with a swimming pool beneath","si":"expedition","blurb":"moderate hike. ~64 m fall on Maderas above Mérida, with a swimming pool beneath","commission":"dormant","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"expedition":"primary","wellness":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Punta Jesús María sandbar","si_tag":"expedition","tier":"essential","source":"https://ometepenicaragua.com/charcoverde/index.php","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"long sandbar spit reaching into the lake, framed views of both volcanoes; classic sunset point. price","si":"expedition","blurb":"long sandbar spit reaching into the lake, framed views of both volcanoes; classic sunset point. price","when":"Dry season Dec–Apr","commission":"dormant","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"expedition":"primary","wellness":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Ojo de Agua natural spring","si_tag":"wellness","tier":"essential","source":"https://ometepenicaragua.com/volcanoes/","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"underground-fed mineral swimming holes between the volcanoes; the island''s slow-morning ritual. price","si":"wellness","blurb":"underground-fed mineral swimming holes between the volcanoes; the island''s slow-morning ritual. price","when":"Dry season Dec–Apr","commission":"dormant","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["wellness"],"shelf_fit":{"wellness":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Charco Verde Nature Reserve","si_tag":"wellness","tier":"essential","source":"https://travelmademedoit.com/charco-verde-ometepe/","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"algae-green lagoon and lake beaches on Concepción''s south side, with the Mirador del Diablo lookout above. price","si":"wellness","blurb":"algae-green lagoon and lake beaches on Concepción''s south side, with the Mirador del Diablo lookout above. price","when":"Dry season Dec–Apr","commission":"dormant","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["wellness"],"shelf_fit":{"wellness":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Pre-Columbian petroglyphs (1,700+)","si_tag":"Culture/Romance","tier":"essential","source":"https://www.dreambigtravelfarblog.com/blog/ometepe-nicaragua","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"1,700+ carvings across 100+ sites; densest at Finca Magdalena; half-submerged carved stones near Tichana past San Ramón. price","si":"romance","blurb":"1,700+ carvings across 100+ sites; densest at Finca Magdalena; half-submerged carved stones near Tichana past San Ramón. price","when":"Dry season Dec–Apr","commission":"dormant","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["Culture/Romance","culture","romance"],"shelf_fit":{"Culture/Romance":"evidenced","culture":"evidenced","romance":"primary","wellness":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed","si_raw":"Culture/Romance","si_map_basis":"normalised from free text ''Culture/Romance'' by gen_normalise_jewel_si"}],"faq":[{"q":"What makes Ometepe Island special?","a":"Ometepe is the largest island in a freshwater lake in the world and a UNESCO Biosphere Reserve since 2010, formed by two volcanoes — active Concepción (1,610 m) and dormant Maderas (1,394 m) — joined by the Isthmus of Istián across roughly 276 km². It also holds over 1,700 pre-Columbian petroglyphs across more than 100 documented sites.","source":"en.unesco.org; lacgeo.com, Accessed 2026-07-07","si_tag":"expedition"},{"q":"How hard are the Ometepe volcano hikes?","a":"Both are serious. Concepción is a strenuous ~10-hour dawn-start climb; Maderas is ~8 hours via a ~4.5 km trail from Balgüe / Finca Magdalena, with a crater lagoon you can swim in at the summit. A licensed local guide is mandatory for both because the upper slopes are exposed, muddy, and cloud-forest-slick.","source":"ometepenicaragua.com; alongdustyroads.com, Accessed 2026-07-07","si_tag":"expedition"},{"q":"Where can you swim on Ometepe?","a":"Ojo de Agua (\"eye of the water\") is the island''s signature spot — a natural mineral swimming hole fed by an underground river originating on Volcán Maderas, about 2 km from Santo Domingo. Go early or late to avoid crowds. Maderas'' summit crater lagoon and designated lake beaches are the other locally advised swims.","source":"ometepenicaragua.com, Accessed 2026-07-07","si_tag":"wellness"},{"q":"Where do couples stay on Ometepe?","a":"Ometepe skews to off-grid eco-lodges rather than resorts. Totoco Eco-Lodge (8 design cabins on Maderas'' slopes, lake-and-Concepción views, farm-to-table dining), Finca del Sol (a 100% sustainable eco-lodge with permaculture farm), and Hacienda Mérida give the quiet, unscripted, two-people-and-a-volcano energy.","source":"steppestravel.com; hotelfincadelsol.com, Accessed 2026-07-07","si_tag":"romance"},{"q":"What''s the real risk to plan for?","a":"Two things: political detention and remoteness. And there is no trauma-grade care on-island — comprehensive care exists only in Managua, so a serious case realistically means Managua then a US medical evacuation.","source":"https://www.gov.uk/foreign-travel-advice/nicaragua","si_tag":"safety"},{"q":"Is climbing an active volcano here dangerous?","a":"Concepción is an active stratovolcano (its last significant ash event was March 2010), and its summit hike is strenuous, exposed, and dawn-started; Maderas is dormant but steep, muddy, and cloud-forest-slick.","source":"ometepenicaragua.com, Accessed 2026-07-07","si_tag":"safety"}],"seo":{"jsonld_type":"TouristDestination","search_language":"es-NI","local_keywords":["Isla de Ometepe qué hacer","Volcán Concepción","Volcán Maderas laguna cráter","Ojo de Agua Ometepe","cascada San Ramón Ometepe","kayak Río Istián","petroglifos Ometepe","ferry San Jorge Ometepe"],"hreflang":["en","es-NI"],"primary_keyword":"Ometepe Island","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-20","last_verified_basis":"safety.fcdo.read","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/nicaragua","read":"2026-08-20T14:55:16Z","source_updated":"2025-12-10T13:20:42+00:00"}]},"content_freshness":"2026-07-07"},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"wellness","status":"live"}],"ultra":[{"name":"Totoco Eco-Lodge","location":"Balgüe","price_tier":"mid/boutique-eco","commission_path":"dormant","source":"https://www.steppestravel.com/accommodation/totoco-eco-lodge/"},{"name":"Finca del Sol Eco Lodge","location":"Maderas base","price_tier":"mid/eco","commission_path":"dormant","source":"https://hotelfincadelsol.com/"},{"name":"Hacienda Mérida","location":"Mérida","price_tier":"value/mid","commission_path":"dormant","source":"https://www.hmerida.com/espanol/activity/1"}],"source_verified":null,"hero":{"query":"Ometepe Island, Nicaragua, Nicaragua"},"geo":{"lat":11.5,"lng":-85.5833},"orbit":[{"id":"granada-nicaragua","jewels":7,"si":["culture"]},{"id":"san-juan-del-sur-nicaragua","jewels":7,"si":["tropical","romance"]}],"orbit_country":[]}'::jsonb, 73),
  ('osa-peninsula-corcovado-costa-rica', '10S', 'Osa Peninsula / Corcovado', 'Costa Rica', 'Corcovado rainforest at the continent''s edge', 'live', 'verified', 'mountainValley', 'Costa Rica', '{"expedition","diveglobal"}', '{}', '{"comfort","premier","ultra"}', null, null, '{"key_facts":["Corcovado holds 2.5% of the world''s biodiversity in 41,800 hectares — ''the most biologically intense place on Earth'' (National Geographic)","Certified guide LEGALLY MANDATORY for all Corcovado entry (SINAC rule since Feb 1 2014)","Caño Island is Costa Rica''s #2 dive site (after Cocos), 30–100+ ft viz, capped at 120 visitors/day","Cocos Island = liveaboard-only pilgrimage, ~36-hr sail from Puntarenas, world''s most consistent schooling hammerheads","Golfo Dulce is one of only four tropical fjords on Earth and hosts BOTH hemispheres'' humpback populations"],"safety":{"emergency":"911","book_enabled":true,"air_access_verified":true,"air_access":"SJO → Drake Bay (DRK) / Puerto Jiménez (PJM) daily small-strip flights (~40–45 min); or 6–8 hr overland 4×4 drive","remote_flag":true,"medevac_note":"Deep-rural; nearest clinic Puerto Jiménez → San José for major care; Sirena has no road; Cocos ~36 hr by sea","hazards":["tide-timed river crossings (crocodile + bull shark at Rio Sirena/Rio Claro mouths)","jungle heat/humidity","Pacific rip currents","venomous snakes (fer-de-lance)","no-fly-after-diving (Caño + Cocos)"],"malaria":"low but present in region; Corcovado itself generally not a malaria concern — consult travel clinic","dengue":"primary mosquito risk; spikes May–Nov rainy season (CR 31,000+ cases 2024)","water":"potable in serviced areas; follow lodge guidance in deep-Osa","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/costa-rica","read":"2026-08-20T14:54:18Z","page_updated":"2026-05-19T11:42:25+01:00","source_country":"costa-rica","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"terrestrial_peak":"mid-Dec–Apr (dry, Corcovado access best)","green_season":"May–Nov (lush, some lodge closures, access degrades)","whale_season":"Jul–Nov Southern humpback (prime late Aug–Sep) + Nov–Feb Northern humpback","cocos_hammerhead_peak":"Jun–Dec","curve_start":"early-mid December","fire_date":"late November (curve-start − 1–2 wks); secondary early-July for whale+hammerhead","booking_lead":"eco-lodges 3–6 mo; Sirena permits 3–4 mo; Cocos liveaboard 6–18 mo","sharpen_note":"sharpen on live tracking — windows drift year to year"},"jewels":[{"name":"Sirena Ranger Station, Corcovado","si_tag":"expedition","tier":"premier","source":"https://vamosrentacar.com/blog/corcovado-national-park-sirena-station/","si":"expedition","commission":"guided trek + Sirena overnight via DMC; margin on guide service","wells":["stay"],"wells_basis":"derived from name/blurb/hook","blurb":"tapir ~70% overnight, all 4 monkey species, scarlet macaw near-guaranteed, peccary herds 30+","blurb_note":"recovered from orphaned field `highlight` 2026-08-22","si_all":["expedition"],"shelf_fit":{"diveglobal":"destination","expedition":"primary"},"commission_lane":["DMC","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Caño Island Biological Reserve","si_tag":"diveglobal","tier":"premier","source":"https://www.entercostarica.com/attractions/national-parks-and-refuges/cano-island","si":"diveglobal","commission":"day-dive/snorkel net-rate/referral","wells":["activities"],"wells_basis":"derived from name/blurb/hook","blurb":"CR #2 dive site, 30–100+ ft viz, sharks/rays/turtles, 120-pax/day cap","blurb_note":"recovered from orphaned field `highlight` 2026-08-22","si_all":["diveglobal"],"shelf_fit":{"diveglobal":"primary","expedition":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Cocos Island National Park (UNESCO)","si_tag":"diveglobal","tier":"ultra","source":"https://www.aggressor.com/destination/Cocos","si":"diveglobal","commission":"own CLIA/DLA lane (Aggressor/Undersea Hunter)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","blurb":"world''s most consistent schooling hammerheads; liveaboard-only, 36-hr sail from Puntarenas","blurb_note":"recovered from orphaned field `highlight` 2026-08-22","si_all":["diveglobal"],"shelf_fit":{"diveglobal":"primary","expedition":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Golfo Dulce (tropical fjord)","si_tag":"WILDLIFE_NATURE/RHN","tier":"premier","source":"https://www.nicuesalodge.com/blog/witness-the-wonder-humpback-migration-in-costa-ricas-golfo-dulce","si":"romance","commission":"lodge-bundled boat tour","wells":["activities"],"wells_basis":"pass 2 — text","blurb":"one of 4 tropical fjords on Earth; both hemispheres'' humpbacks; dolphins, mangroves","blurb_note":"recovered from orphaned field `highlight` 2026-08-22","si_all":["WILDLIFE_NATURE/RHN","romance","wildlife"],"shelf_fit":{"WILDLIFE_NATURE/RHN":"evidenced","diveglobal":"destination","expedition":"destination","romance":"primary","wildlife":"evidenced"},"commission_lane":["bundle","hotel"],"commission_embedded":false,"commission_basis":"lane","si_raw":"WILDLIFE_NATURE/RHN","si_map_basis":"normalised from free text ''WILDLIFE_NATURE/RHN'' by gen_normalise_jewel_si"},{"name":"Drake Bay","si_tag":"DIVE/GEA","tier":"comfort","source":"https://www.copadearbol.com/osa-peninsula-eco-lodge/","si":"expedition","commission":"lodge + activity referral","wells":["stay"],"wells_basis":"derived from name/blurb/hook","blurb":"northern-Osa gateway to Caño Island + Corcovado San Pedrillo; sportfishing, night tours","blurb_note":"recovered from orphaned field `highlight` 2026-08-22","si_all":["DIVE/GEA","diveglobal","expedition"],"shelf_fit":{"DIVE/GEA":"evidenced","diveglobal":"evidenced","expedition":"primary"},"commission_lane":["hotel"],"commission_embedded":false,"commission_basis":"lane","si_raw":"DIVE/GEA","si_map_basis":"normalised from free text ''DIVE/GEA'' by gen_normalise_jewel_si"},{"name":"Puerto Jiménez","si_tag":"expedition","tier":"comfort","source":"https://mytanfeet.com/driving-in-costa-rica/puerto-jimenez-osa-peninsula/","si":"expedition","commission":"gateway nights + transfers","wells":["activities"],"wells_basis":"pass 2 — text","blurb":"frontier town + PJM airstrip; Golfo Dulce + southern Corcovado gateway","blurb_note":"recovered from orphaned field `highlight` 2026-08-22","si_all":["expedition"],"shelf_fit":{"diveglobal":"destination","expedition":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Matapalo surf & waterfalls","si_tag":"expedition","tier":"comfort","source":"https://www.crsurfzone.com/corcovado-national-park.html","si":"expedition","commission":"lodge-bundled excursion","wells":["activities"],"wells_basis":"pass 2 — text","blurb":"secluded breaks + jungle cascades at peninsula tip","blurb_note":"recovered from orphaned field `highlight` 2026-08-22","si_all":["expedition"],"shelf_fit":{"diveglobal":"destination","expedition":"primary"},"commission_lane":["bundle","hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Whale-watching, Golfo Dulce","si_tag":"WILDLIFE_NATURE","tier":"premier","source":"https://www.nicuesalodge.com/blog/witness-the-wonder-humpback-migration-in-costa-ricas-golfo-dulce","si":"wildlife","commission":"guided boat referral","wells":["activities"],"wells_basis":"derived from name/blurb/hook","blurb":"both hemispheres'' humpbacks (Jul–Nov Southern + Nov–Feb Northern)","blurb_note":"recovered from orphaned field `highlight` 2026-08-22","si_all":["wildlife"],"shelf_fit":{"diveglobal":"destination","expedition":"destination","wildlife":"primary"},"commission_lane":["guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Cacao finca / farm-to-bar chocolate","si_tag":"expedition","tier":"comfort","source":"https://www.osawild.travel/locations/","si":"expedition","commission":"referral","wells":["activities"],"wells_basis":"derived from name/blurb/hook","blurb":"Indigenous + smallholder cacao experience","blurb_note":"recovered from orphaned field `highlight` 2026-08-22","si_all":["expedition"],"shelf_fit":{"diveglobal":"destination","expedition":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"}],"faq":[{"q":"Do you need a guide to hike Corcovado National Park?","a":"Yes — a certified guide is legally mandatory for all Corcovado entry, a SINAC rule in force since February 1, 2014 and enforced at every ranger station, where unguided visitors are turned away. Build the guided-trek product; there is no compliant self-guided version to sell.","source":"Wikipedia — Corcovado National Park, 2026-07-06","si_tag":"expedition"},{"q":"Can you dive Cocos Island on a day trip?","a":"No. Cocos is liveaboard-only — it lies ~342 mi off the Pacific coast, an ~36-hr open-ocean crossing from Puntarenas, and is sold as 8/10/12-night charters (15/21/27 dives) via Aggressor or Undersea Hunter. Berths book 6–18 months out, so plan far ahead.","source":"aggressor.com, 2026-07-06","si_tag":"diveglobal"},{"q":"Are the Osa eco-lodges right for a honeymoon?","a":"Yes — the Osa is honeymoon-grade seclusion without the resort cliché: private-reserve bungalows over the Pacific, canopy suites and no Wi-Fi. Lapa Rios alone offers 16 ocean-view bungalows across 1,000 protected acres, and remote lodges bundle meals, guided excursions and transfers by necessity.","source":"laparios.com, 2026-07-06","si_tag":"romance"},{"q":"When can you see whales in Golfo Dulce?","a":"Golfo Dulce — one of only four tropical fjords on Earth — draws both hemispheres'' humpbacks, so the season is unusually long: Southern-hemisphere humpbacks calve July–November (prime late Aug–Sept), and Northern-hemisphere humpbacks arrive November–February.","source":"nicuesalodge.com, 2026-07-06","si_tag":"wildlife"},{"q":"What''s the real risk to plan for on a Corcovado trek?","a":"The tide-timed river crossings. Rio Sirena and Rio Claro are the most dangerous, with American crocodiles and bull sharks patrolling the river mouths, so guides cross only at low tide and never in storms. This — plus jungle heat and deep-remote medevac — is the true gatekeeper, above petty crime.","source":"crsurfzone.com, 2026-07-06","si_tag":"safety"},{"q":"Is diving Cocos Island dangerous?","a":"It is advanced diving in a strong-current, deeply remote environment. DAN membership and dive insurance are essential, no-fly-after-diving surface intervals apply, and because the site is ~36 hr from land the vessel itself is the only evacuation. Not a first-timer''s trip.","source":"aggressor.com, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Osa Peninsula & Corcovado, Costa Rica — The Most Biologically Intense Place on Earth | TravelWell.World","search_language":"es-CR","local_keywords":["Parque Nacional Corcovado","Península de Osa","Isla del Coco buceo","Bahía Drake","Golfo Dulce ballenas","Puerto Jiménez"],"hreflang":["en","es-CR"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-06","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-06","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/costa-rica","read":"2026-08-20T14:54:18Z","source_updated":"2026-05-19T11:42:25+01:00"}]},"long_tail":["Corcovado guided tour","Sirena station Corcovado","Caño Island diving Drake Bay","Cocos Island liveaboard hammerhead","Osa Peninsula luxury eco lodge","Golfo Dulce whale watching"]},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":["expedition","diveglobal"],"ultra":[{"name":"Lapa Rios","operator":"Böëna / Cayuga Collection","location":"above Corcovado","earn":"Virtuoso/consortia; AoR via ST Costa Rica DMC","tier":"ultra"},{"name":"El Remanso","location":"Puerto Jiménez / private beach","earn":"Virtuoso/consortia + full-property buyout","tier":"ultra"},{"name":"Copa de Árbol","location":"Drake Bay","earn":"consortia","tier":"ultra"},{"name":"Playa Cativo","location":"Golfo Dulce","earn":"consortia + private-reserve buyout","tier":"ultra"},{"name":"Aguila de Osa","location":"Drake Bay","earn":"consortia + Caño Island dive referral","tier":"ULTRA/PREMIUM"},{"name":"Cocos private liveaboard charter","operator":"Aggressor / Undersea Hunter","earn":"own CLIA/DLA lane — AoR/MoR via DLA relationship","tier":"ultra"},{"name":"Kasiiya Papagayo","correction":"in GUANACASTE, not Osa — do not sell as Osa property","tier":"N/A"}],"source_verified":"2026-07-06","hero":{"query":"Osa Peninsula / Corcovado, Costa Rica"},"geo":{"lat":8.54,"lng":-83.59},"orbit":[{"id":"guanacaste-costa-rica","jewels":10,"si":["tropical","expedition","liveaboard","wellness","wildlife"]},{"id":"la-fortuna-arenal-costa-rica","jewels":10,"si":["expedition","romance","wellness"]},{"id":"manuel-antonio-costa-rica","jewels":9,"si":["tropical","expedition","wildlife"]},{"id":"monteverde-costa-rica","jewels":12,"si":["expedition","wildlife","romance"]},{"id":"nosara-costa-rica","jewels":10,"si":["tropical","expedition","wellness"]},{"id":"puerto-viejo-costa-rica","jewels":10,"si":["tropical","expedition","culture","wildlife","ocean"]},{"id":"san-jose-costa-rica","jewels":13,"si":["culture","expedition"]},{"id":"tortuguero-costa-rica","jewels":6,"si":["expedition","river"]}],"orbit_country":[]}'::jsonb, 74),
  ('ouro-preto-tiradentes-brazil', '10S', 'Ouro Preto, Tiradentes & Colonial Minas, Brazil', 'Brazil', 'Gold-rush baroque in the mountains', 'live', 'verified', 'venice', 'Rio & The Southeast Coast', '{"romance","culture","culinary"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":null,"safety":{"emergency":"190","emergency_medical":"192","advisory_source":"https://www.gov.uk/foreign-travel-advice/brazil","book_enabled":true,"air_access_verified":{"international":"CNF (Belo Horizonte / Confins — Tancredo Neves Intl)","gateway_transfer":"~87 mi / ~2 hrs by road to Ouro Preto"},"water":"bottled recommended (tap not advised for visitors)","caveats":["Steep, uneven, car-free cobblestone at altitude — #1 injury risk; sturdy shoes; flag limited mobility","Mountain-road transfers between towns; avoid night driving; driver-guide/DMC preferred","Mina da Passagem = guided underground descent only (trolley to 120 m)","Trauma → Belo Horizonte private hospitals (~1.5–2 hrs) → US medical evacuation; confirm evac coverage","Dengue precautions (repellent; worse in warm/wet off-season Oct–Mar)"],"fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/brazil","read":"2026-08-20T14:54:23Z","page_updated":"2026-05-11T12:32:48+01:00","source_country":"brazil","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"River areas in the west of Amazonas State","lvl":3,"posture":"all-but-essential","note":"Along the Amazon River and its tributaries west of Codajás and east of Belém do Solimões; any part of the Itaquaí River; any part of the Japurá River or its tributaries; and the Rio Negro and its tributaries north or west of Barcelos."}],"fcdo_zones_provenance":{"file":"src/data/safety.json","ref":"f8666636bc25790e0c9643ad5656f8d9fea37bf6","ref_committed":"2026-08-30T05:44:55Z","country_iso2":"BR","summary":"The FCDO advise